function header_html(string $title): void { global $page,$pdo; $f=$_SESSION['flash']??null;unset($_SESSION['flash']);$shop=setting($pdo,'shop_name','SGAS');$brand=setting($pdo,'brand_color','#0b432a');$sidebar=setting($pdo,'sidebar_mode','normal');?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="<?=e($brand)?>"><title><?=e($title)?> — <?=e($shop)?></title><link rel="stylesheet" href="assets/app.css?v=20260831-36"><link rel="stylesheet" href="assets/bill.css?v=20260902-10"><link rel="stylesheet" href="assets/sidebar.css?v=20260902-3"><link rel="stylesheet" href="assets/reports.css?v=20260902-4"><link rel="stylesheet" href="assets/products.css?v=20260901-1"><link rel="stylesheet" href="assets/categories.css?v=20260901-1"><link rel="stylesheet" href="assets/ledger.css?v=20260901-1"><link rel="stylesheet" href="assets/customers.css?v=20260901-1"><link rel="stylesheet" href="assets/dashboard.css?v=20260901-1"><link rel="stylesheet" href="assets/payments.css?v=20260901-1"><link rel="stylesheet" href="assets/settings.css?v=20260902-1"></head><body class="page-<?=e($page)?> sidebar-<?=e($sidebar)?> mobile-menu-<?=e(setting($pdo,'mobile_menu','collapsed'))?>" style="--brand-color:<?=e($brand)?>"><?php if(logged_in()):?><button type="button" class="menu-toggle no-print" aria-label="Open menu" aria-expanded="false">☰</button><nav class="no-print"><strong><?=e($shop)?></strong><a href="index.php">Dashboard</a><a href="?page=new_bill">New Bill</a><a href="?page=bills">Bills</a><a href="?page=customers">Customers</a><a href="?page=products">Products</a><a href="?page=categories">Categories</a><a href="?page=payments">Receive Payment</a><a href="?page=reports">Reports</a><a href="?page=whatsapp_reminders">WhatsApp</a><a href="?page=settings">Settings</a><a href="backup.php">Backup</a><a href="?page=logout">Logout</a></nav><?php endif;?><main class="wrap"><?php if($f):?><div class="notice <?=$f['type']==='error'?'error':''?>"><?=e($f['msg'])?></div><?php endif;?><?php }
