if($page==='login'){header_html('Sign in');?><div class="card login"><h1>SGAS</h1><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><p><label>Username</label><input name="username" autocomplete="username" required autofocus></p><p><label>Password</label><input type="password" name="password" autocomplete="current-password" required></p><button>Sign in</button></form></div><?php footer_html();exit;}

if($page==='dashboard'){$customerRows=$pdo->query('SELECT id,name,mobile,address FROM customers ORDER BY name')->fetchAll();$customers=count($customerRows);$products=(int)$pdo->query('SELECT COUNT(*) FROM products')->fetchColumn();$bills=(int)$pdo->query("SELECT COUNT(*) FROM bills WHERE status='active'")->fetchColumn();$todayStart=date('Y-m-d 00:00:00');$tomorrowStart=date('Y-m-d 00:00:00',strtotime('+1 day'));$s=$pdo->prepare("SELECT COALESCE(SUM(subtotal),0) FROM bills WHERE status='active' AND created_at>=? AND created_at<?");$s->execute([$todayStart,$tomorrowStart]);$todayValue=(float)$s->fetchColumn();$billReceived=(float)$pdo->query("SELECT COALESCE(SUM(amount_received),0) FROM bills WHERE status='active'")->fetchColumn();$paymentsReceived=(float)$pdo->query('SELECT COALESCE(SUM(amount),0) FROM payments')->fetchColumn();$totalReceived=$billReceived+$paymentsReceived;$outstanding=[];$totalOutstanding=0.0;foreach($customerRows as $c){$c['balance']=customer_balance($pdo,(int)$c['id']);$c['phone']=whatsapp_number($c['mobile']);if($c['balance']>0){$totalOutstanding+=(float)$c['balance'];$outstanding[]=$c;}}usort($outstanding,fn($a,$b)=>$b['balance']<=>$a['balance']);$outstanding=array_slice($outstanding,0,5);$recent=$pdo->query("SELECT b.id,b.bill_no,b.subtotal,b.created_at,c.name customer FROM bills b JOIN customers c ON c.id=b.customer_id WHERE b.status='active' ORDER BY b.id DESC LIMIT 5")->fetchAll();header_html('Dashboard');?><section class="dashboard-head"><div><h1>Business Overview</h1><p>Welcome back. Here is your SGAS billing summary.</p></div><div class="dashboard-date"><?=e(date('l, d F Y'))?></div></section><div class="dashboard-stats"><div class="card dashboard-stat"><small>Total Customers</small><b><?=$customers?></b></div><div class="card dashboard-stat"><small>Products</small><b><?=$products?></b></div><div class="card dashboard-stat"><small>Total Bills</small><b><?=$bills?></b></div><div class="card dashboard-stat"><small>Today's Bill Value</small><b>₹<?=money($todayValue)?></b></div><div class="card dashboard-stat"><small>Amount Received</small><b>₹<?=money($totalReceived)?></b></div><div class="card dashboard-stat outstanding"><small>Total Outstanding</small><b>₹<?=money($totalOutstanding)?></b></div></div><div class="card dashboard-quick"><h2>Quick Actions</h2><div class="dashboard-quick-actions"><a class="btn" href="?page=new_bill"><span class="icon">＋</span>New Bill</a><a class="btn secondary" href="?page=payments"><span class="icon">₹</span>Receive Payment</a><a class="btn secondary" href="?page=customers"><span class="icon">♙</span>Add Customer</a><a class="btn secondary" href="?page=products"><span class="icon">□</span>Add Product</a></div></div><div class="dashboard-panels"><section class="card dashboard-panel"><div class="dashboard-panel-head"><h2>Recent Bills</h2><a href="?page=bills">View All Bills</a></div><div class="dashboard-table-wrap"><table class="dashboard-table"><thead><tr><th>Bill No.</th><th>Date</th><th>Customer</th><th class="right">Amount</th><th>Actions</th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td>#<?=str_pad((string)$r['bill_no'],4,'0',STR_PAD_LEFT)?></td><td><?=e(date('d-m-Y',strtotime($r['created_at'])))?></td><td><?=e($r['customer'])?></td><td class="right"><b>₹<?=money($r['subtotal'])?></b></td><td><div class="dashboard-row-actions"><a class="btn secondary" href="?page=view_bill&amp;id=<?=$r['id']?>">View</a><a class="btn" href="?page=new_bill&amp;id=<?=$r['id']?>">Edit</a></div></td></tr><?php endforeach;if(!$recent):?><tr><td class="dashboard-empty" colspan="5">No bills created yet.</td></tr><?php endif;?></tbody></table></div></section><section class="card dashboard-panel"><div class="dashboard-panel-head"><h2>Top Outstanding</h2><a href="?page=reports#outstanding">View Report</a></div><div class="dashboard-table-wrap"><table class="dashboard-table"><thead><tr><th>Customer</th><th class="right">Balance</th><th>Actions</th></tr></thead><tbody><?php foreach(