if($page==='customers'){$edit=null;$openingLocked=false;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT c.*,(EXISTS(SELECT 1 FROM bills WHERE customer_id=c.id) OR EXISTS(SELECT 1 FROM payments WHERE customer_id=c.id)) balance_locked FROM customers c WHERE c.id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();$openingLocked=$edit&&(bool)$edit['balance_locked'];}$rows=$pdo->query('SELECT * FROM customers ORDER BY name')->fetchAll();$totalOutstanding=0.0;$readyCount=0;foreach($rows as &$r){$r['balance']=customer_balance($pdo,(int)$r['id']);$r['phone']=whatsapp_number($r['mobile']);if($r['balance']>0)$totalOutstanding+=(float)$r['balance'];if($r['phone'])$readyCount++;}unset($r);header_html('Customers');?><section class="customers-page-head"><div><h1>Customers & Balances</h1><p>Manage customer details, WhatsApp numbers and outstanding balances.</p></div><div class="customer-summary"><div class="customer-summary-card"><small>Customers</small><b><?=count($rows)?></b></div><div class="customer-summary-card"><small>Outstanding</small><b>₹<?=money($totalOutstanding)?></b></div><div class="customer-summary-card"><small>WhatsApp Ready</small><b><?=$readyCount?></b></div></div></section><div class="card customer-editor"><div class="customer-editor-head"><h2><?=$edit?'Edit Customer':'Add Customer'?></h2><?php if($edit):?><a href="?page=customers">Cancel editing</a><?php endif;?></div><form method="post" class="customer-form"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="save_customer"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><p><label>Name</label><input name="name" value="<?=e($edit['name']??'')?>" required autofocus></p><p><label>WhatsApp Number</label><input name="mobile" inputmode="tel" placeholder="9677811194" value="<?=e($edit['mobile']??'')?>"><small class="muted">10-digit Indian number</small></p><p><label>Address</label><textarea name="address"><?=e($edit['address']??'')?></textarea></p><p><label>Opening Balance</label><input type="number" step="0.01" name="opening_balance" value="<?=e($edit['opening_balance']??'0')?>" <?=$openingLocked?'readonly':''?>><?php if($openingLocked):?><small class="opening-balance-note">Locked because transactions exist.</small><?php endif;?></p><div class="customer-form-actions"><button type="submit"><?=$edit?'Update':'Save'?> Customer</button><?php if($edit):?><a class="btn secondary" href="?page=customers">Cancel</a><?php endif;?></div></form></div><div class="card customer-list-card"><div class="customer-toolbar"><h2>Customer List</h2><input id="customer-list-search" type="search" placeholder="Search name, mobile or address…" autocomplete="off"></div><div class="customer-table-wrap"><table class="customer-table"><thead><tr><th>S.No</th><th>Customer</th><th>WhatsApp</th><th class="right">Balance</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $i=>$r):$msg=str_replace(['{name}','{balance}'],[$r['name'],money($r['balance'])],setting($pdo,'reminder_tamil'));?><tr data-customer-row data-search="<?=e(strtolower($r['name'].' '.$r['mobile'].' '.$r['address']))?>"><td class="customer-sno"><?=$i+1?></td><td class="customer-identity"><b><?=e($r['name'])?></b><small><?=e($r['address']?:'Address not added')?></small></td><td><?php if($r['phone']):?>+<?=e($r['phone'])?><br><span class="customer-whatsapp-status ready">Ready</span><?php elseif($r['mobile']):?><?=e($r['mobile'])?><br><span class="customer-whatsapp-status missing">Check number</span><?php else:?><span class="customer-whatsapp-status missing">Not added</span><?php endif;?></td><td class="right customer-balance <?=$r['balance']>0?'due':'clear'?>">₹<?=money($r['balance'])?></td><td><div class="customer-row-actions"><a class="btn secondary" href="?page=customers&amp;edit=<?=$r['id']?>">Edit</a><a class="btn secondary" href="?page=ledger&amp;customer_id=<?=$r['id']?>">Ledger</a><?php if($r['phone']):?><a class="btn whatsapp-btn" target="_blank" href="https://wa.me/<?=e($r['phone'])?>?text=<?=rawurlencode($msg)?>">WhatsApp</a><?php endif;?></div></td></tr><?php endforeach;?><tr id="customer-filter-empty" hidden><td class="customer-list-empty" colspan="5">No matching customers found.</td></tr></tbody></table></div></div><script>document.addEventListener('DOMContentLoaded',()=>{const search=document.getElementById('customer-list-search'),rows=[...document.querySelectorAll('[data-customer-row]')],empty=document.getElementById('customer-filter-empty');const apply=()=>{const q=search.value.trim().toLowerCase();let visible=0;rows.forEach(row=>{const show=!q||row.dataset.search.includes(q);row.hidden=!show;if(show)row.querySelector('.customer-sno').textContent=++visible;});empty.hidden=visible!==0;};search.addEventListener('input',apply);apply();});</script><?php footer_html();exit;}

if($page==='ledger'){$customers=$pdo->query('SELECT id,name,mobile,address,opening_balance FROM customers ORDER BY name')->fetchAll();foreach($customers as &$c)$c['balance']=customer_balance($pdo,(int)$c['id']);unset($c);$customerId=(int)($_GET['customer_id']??0);$from=trim($_GET['from']??'');$to=trim($_GET['to']??'');if($from!==''&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from))$from='';if($to!==''&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to))$to='';if($from!==''&&$to!==''&&$from>$to)[$from,$to]=[$to,$from];$ledger=$customerId?customer_ledger($pdo,$customerId):['customer'=>null,'rows'=>[],'balance'=>0];$customer=$ledger['customer'];$displayRows=[];$periodOpening=$customer?(float)$customer['opening_balance']:0.0;$periodDebit=0.0;$periodCredit=0.0;$periodClosing=$periodOpening;if($customer){foreach(array_slice($ledger['rows'],1) as $event){$day=substr((string)$event['timestamp'],0,10);if($from!==''&&$day<$from){$periodOpening=round($periodOpening+(float)$event['delta'],2);continue;}if($to!==''&&$day>$to)continue;$periodClosing=round($periodClosing+(float)$event['delta'],2);$event['balance']=$periodClosing;$displayRows[]=$event;if($event['delta']>0)$periodDebit+=(float)$event['delta'];elseif($event['delta']<0)$periodCredit+=abs((float)$event['delta']);}$periodClosing=round($periodOpening+$periodDebit-$periodCredit,2);$running=$periodOpening;foreach($displayRows as &$event){$running=round($running+(float)$event['delta'],2);$event['balance']=$running;}unset($event);}$selected=null;foreach($customers as $candidate)if((int)$candidate['id']===$customerId){$selected=$candidate;break;}header_html('Customer Ledger');?><div class="ledger-page-head"><h1>Customer Ledger</h1><p>View bills, payments and running customer balance.</p></div><form method="get" class="card no-print ledger-selector" id="ledger-selector"><input type="hidden" name="page" value="ledger"><div class="ledger-customer-box"><label>Customer</label><input id="ledger-customer-input" type="search" placeholder="Type customer name or mobile" autocomplete="off" value="<?=e($selected?$selected['name'].' — '.($selected['address']?:$selected['mobile']):'')?>" required><input id="ledger-customer-id" type="hidden" name="customer_id" value="<?=e((string)$customerId)?>"><button class="ledger-customer-clear" type="button" <?=$selected?'':'hidden'?>>×</button><div class="ledger-suggestions" id="ledger-customer-options"><?php foreach($customers as $c):?><button type="button" data-id="<?=$c['id']?>" data-name="<?=e($c['name'])?>" data-address="<?=e($c['address'])?>" data-mobile="<?=e($c['mobile'])?>" data-balance="<?=e(money($c['balance']))?>" data-search="<?=e(strtolower($c['name'].' '.$c['mobile'].' '.$c['address']))?>"><strong><?=e($c['name'])?></strong><small><?=e($c['address']?:$c['mobile'])?> · Balance ₹<?=money($c['balance'])?></small></button><?php endforeach;?></div><div class="ledger-selected-balance" id="ledger-selected-balance"><?=$selected?'Current balance: ₹'.money($selected['balance']):'Select a customer from the suggestions.'?></div></div><button type="submit">Open Ledger</button></form><?php if($customer):$phone=whatsapp_number($customer['mobile']);$periodLabel=($from||$to)?(($from?date('d-m-Y',strtotime($from)):'Beginning').' to '.($to?date('d-m-Y',strtotime($to)):'Today')):'All transactions';$msg='SGAS Customer Ledger'."\n".$customer['name']."\n".$periodLabel."\nOpening: ₹".money($periodOpening)."\nDebit: ₹".money($periodDebit)."\nCredit: ₹".money($periodCredit)."\nClosing Balance: ₹".money($periodClosing);$pdfName='SGAS-Ledger-'.preg_replace('/[^A-Za-z0-9_-]+/','-',$customer['name']).'.pdf';?><form method="get" class="ledger-tools no-print"><input type="hidden" name="page" value="ledger"><input type="hidden" name="customer_id" value="<?=$customerId?>"><p><label>From</label><input type="date" name="from" value="<?=e($from)?>"></p><p><label>To</label><input type="date" name="to" value="<?=e($to)?>"></p><button type="submit">Apply Dates</button><a class="btn secondary" href="?page=ledger&amp;customer_id=<?=$customerId?>">Clear Dates</a><button type="button" onclick="window.print()">Print Ledger</button><button type="button" onclick="downloadDocumentPdf('<?=e($pdfName)?>')">Download PDF</button><button type="button" onclick="shareDocumentPdf('<?=e($pdfName)?>')">Share PDF</button><?php if($phone):?><a class="btn whatsapp-btn" target="_blank" href="https://wa.me/<?=e($phone)?>?text=<?=rawurlencode($msg)?>">WhatsApp Statement</a><?php endif;?></form><div class="ledger-summary"><div class="card"><small>Opening Balance</small><b>₹<?=money($periodOpening)?></b></div><div class="card"><small>Total Debit</small><b>₹<?=money($periodDebit)?></b></div><div class="card"><small>Total Credit</small><b>₹<?=money($periodCredit)?></b></div><div class="card"><small>Closing Balance</small><b>₹<?=money($periodClosing)?></b></div></div><div class="card pdf-document ledger-print"><div class="ledger-header"><div><h1>SGAS</h1><p>Customer Ledger Statement · <?=e($periodLabel)?></p></div><div><b><?=e($customer['name'])?></b><br><?=e($customer['mobile'])?><br><?=nl2br(e($customer['address']))?></div></div><div class="ledger-table-wrap"><table><thead><tr><th>Date</th><th>Particulars</th><th>Bill / Reference</th><th>Details</th><th class="right">Debit</th><th class="right">Credit</th><th class="right">Balance</th></tr></thead><tbody><tr><td>—</td><td>Opening Balance</td><td>—</td><td><?=($from||$to)?'Balance before selected period':'Customer opening balance'?></td><td class="right"><?=$periodOpening>0?'₹'.money($periodOpening):'—'?></td><td class="right"><?=$periodOpening<0?'₹'.money(abs($periodOpening)):'—'?></td><td class="right"><b>₹<?=money($periodOpening)?></b></td></tr><?php foreach($displayRows as $r):?><tr><td><?=e(date('d-m-Y',strtotime($r['timestamp'])))?></td><td><?=e($r['type'])?></td><td><?=e($r['reference'])?></td><td><?=e($r['note'])?></td><td class="right"><?=$r['delta']>0?'₹'.money($r['delta']):'—'?></td><td class="right"><?=$r['delta']<0?'₹'.money(abs($r['delta'])):'—'?></td><td class="right"><b>₹<?=money($r['balance'])?></b></td></tr><?php endforeach;if(!$displayRows):?><tr><td class="ledger-empty" colspan="7">No transactions found for this period.</td></tr><?php endif;?></tbody></table></div><div class="ledger-closing"><span>Closing Balance</span><b>₹<?=money($periodClosing)?></b></div></div><script src="https://cdnjs.cloudflare.com/ajax/libs/html2pdf.js/0.10.1/html2pdf.bundle.min.js"></script><?php endif;?><script>document.addEventListener('DOMContentLoaded',()=>{const input=document.getElementById('ledger-customer-input'),id=document.getElementById('ledger-customer-id'),menu=document.getElementById('ledger-customer-options'),balance=document.getElementById('ledger-selected-balance'),clear=document.querySelector('.ledger-customer-clear'),buttons=[...menu.querySelectorAll('button')];let active=-1;const visible=()=>buttons.filter(b=>!b.hidden);const mark=i=>{const list=visible();if(!list.length)return;active=(i+list.length)%list.length;buttons.forEach(b=>b.classList.remove('active'));list[active].classList.add('active');list[active].scrollIntoView({block:'nearest'});};const show=()=>{const q=input.value.toLowerCase().trim();buttons.forEach(b=>{b.hidden=q!==''&&!b.dataset.search.includes(q);b.classList.remove('active');});active=-1;menu.classList.add('open');if(visible().length)mark(0);};const choose=b=>{id.value=b.dataset.id;input.value=b.dataset.name+' — '+(b.dataset.address||b.dataset.mobile||'No address');balance.textContent='Current balance: ₹'+b.dataset.balance;clear.hidden=false;menu.classList.remove('open');input.setCustomValidity('');};input.addEventListener('focus',show);input.addEventListener('input',()=>{id.value='';clear.hidden=true;balance.textContent='Select a customer from the suggestions.';input.setCustomValidity('Select a customer from the suggestions.');show();});input.addEventListener('keydown',e=>{if(e.key==='ArrowDown'){e.preventDefault();mark(active+1);}else if(e.key==='ArrowUp'){e.preventDefault();mark(active-1);}else if(e.key==='Enter'&&menu.classList.contains('open')&&visible().length){e.preventDefault();choose(visible()[active>=0?active:0]);}else if(e.key==='Escape')menu.classList.remove('open');});buttons.forEach(b=>b.addEventListener('mousedown',e=>{e.preventDefault();choose(b);}));input.addEventListener('blur',()=>setTimeout(()=>menu.classList.remove('open'),160));clear.addEventListener('click',()=>{id.value='';input.value='';balance.textContent='Select a customer from the suggestions.';clear.hidden=true;input.setCustomValidity('');input.focus();show();});document.getElementById('ledger-selector').addEventListener('submit',e=>{if(!id.value){e.preventDefault();input.setCustomValidity('Select a customer from the suggestions.');input.reportValidity();}});});</script><?php footer_html();exit;}

if($page==='payments'){
$customerId=(int)($_GET['customer_id']??0);$from=trim($_GET['from']??'');$to=trim($_GET['to']??'');$status=trim($_GET['status']??'');$method=trim($_GET['method']??'');$search=trim($_GET['q']??'');
if($from!==''&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from))$from='';if($to!==''&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to))$to='';if($from!==''&&$to!==''&&$from>$to)[$from,$to]=[$to,$from];
$customers=$pdo->query('SELECT id,name,mobile,address FROM customers ORDER BY name')->fetchAll();$totalOutstanding=0.0;foreach($customers as &$c){$c['balance']=customer_balance($pdo,(int)$c['id']);if($c['balance']>0)$totalOutstanding+=(float)$c['balance'];}unset($c);
$todayStart=date('Y-m-d 00:00:00');$tomorrowStart=date('Y-m-d 00:00:00',strtotime('+1 day'));$monthStart=date('Y-m-01 00:00:00');$nextMonth=date('Y-m-01 00:00:00',strtotime('first day of next month'));
$s=$pdo->prepare('SELECT COALESCE(SUM(amount),0) FROM payments WHERE created_at>=? AND created_at<?');$s->execute([$todayStart,$tomorrowStart]);$todayCollected=(float)$s->fetchColumn();$s->execute([$monthStart,$nextMonth]);$monthCollected=(float)$s->fetchColumn();$reversedCount=(int)$pdo->query("SELECT COUNT(*) FROM payments WHERE amount<0 OR note LIKE '[REVERSED]%'")->fetchColumn();
$where=[];$params=[];if($customerId){$where[]='p.customer_id=?';$params[]=$customerId;}if($from!==''){$where[]='p.created_at>=?';$params[]=$from.' 00:00:00';}if($to!==''){$where[]='p.created_at<?';$params[]=date('Y-m-d H:i:s',strtotime($to.' +1 day'));}if($method!==''){$where[]='p.note LIKE ?';$params[]='['.$method.']%';}if($status==='active')$where[]="p.amount>0 AND p.note NOT LIKE '[REVERSED]%'";elseif($status==='reversed')$where[]="p.note LIKE '[REVERSED]%'";elseif($status==='reversal')$where[]='p.amount<0';if($search!==''){$where[]='(c.name LIKE ? OR p.note LIKE ? OR CAST(p.id AS CHAR) LIKE ?)';$like='%'.$search.'%';array_push($params,$like,$like,$like);}
$sql='SELECT p.*,c.name customer,c.mobile FROM payments p JOIN customers c ON c.id=p.customer_id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY p.id DESC LIMIT 500';$s=$pdo->prepare($sql);$s->execute($params);$rows=$s->fetchAll();
header_html('Payments');?>
