<div class="payment-stats"><div class="card"><small>Collected Today</small><b>₹<?=money($todayCollected)?></b></div><div class="card"><small>Collected This Month</small><b>₹<?=money($monthCollected)?></b></div><div class="card outstanding"><small>Total Outstanding</small><b>₹<?=money($totalOutstanding)?></b></div><div class="card"><small>Reversed Entries</small><b><?=$reversedCount?></b></div></div>
<section class="card payment-entry" id="record-payment"><div class="payment-section-head"><div><h2>Receive Payment</h2><p>Select a customer and enter the collection details.</p></div><span class="payment-secure">Balance-safe entry</span></div><form method="post" class="payment-form"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="save_payment"><p class="payment-customer-field"><label>Customer</label><select name="customer_id" id="payment-customer" required><option value="">Choose customer</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>" data-balance="<?=e(money($c['balance']))?>" <?=$customerId===$c['id']?'selected':''?>><?=e($c['name'])?> — ₹<?=money($c['balance'])?></option><?php endforeach;?></select><small id="payment-balance">Select a customer to view the current balance.</small></p><p><label>Amount</label><input name="amount" type="number" min="0.01" step="0.01" inputmode="decimal" required placeholder="0.00"></p><p><label>Payment Date</label><input name="payment_date" type="date" value="<?=e(date('Y-m-d'))?>" required></p><p><label>Payment Method</label><select name="payment_method" required><?php $enabledMethods=json_decode(setting($pdo,'payment_methods','["Cash","UPI","Bank Transfer","Cheque"]'),true);if(!is_array($enabledMethods)||!$enabledMethods)$enabledMethods=['Cash'];$defaultMethod=setting($pdo,'default_payment_method','Cash');foreach($enabledMethods as $m):?><option <?=$m===$defaultMethod?'selected':''?>><?=e($m)?></option><?php endforeach;?></select></p><p><label>Reference Number</label><input name="reference" maxlength="80" placeholder="Optional transaction number"></p><p class="payment-note"><label>Note</label><input name="note" maxlength="140" placeholder="Optional note"></p><button type="submit">Save Payment</button></form></section>
<section class="card payment-history"><div class="payment-section-head"><div><h2>Payment History</h2><p>Reversals preserve the original record and restore the customer balance.</p></div><b><?=count($rows)?> entries</b></div><form method="get" class="payment-filters"><input type="hidden" name="page" value="payments"><input type="search" name="q" value="<?=e($search)?>" placeholder="Search customer, ID or reference"><select name="customer_id"><option value="">All customers</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>" <?=$customerId===$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><input type="date" name="from" value="<?=e($from)?>" title="From date"><input type="date" name="to" value="<?=e($to)?>" title="To date"><select name="method"><option value="">All methods</option><?php foreach($enabledMethods as $m):?><option <?=$method===$m?'selected':''?>><?=e($m)?></option><?php endforeach;?></select><select name="status"><option value="">All statuses</option><option value="active" <?=$status==='active'?'selected':''?>>Active</option><option value="reversed" <?=$status==='reversed'?'selected':''?>>Reversed</option><option value="reversal" <?=$status==='reversal'?'selected':''?>>Reversal</option></select><button>Apply</button><a class="btn secondary" href="?page=payments">Clear</a></form><div class="payment-table-wrap"><table class="payment-table"><thead><tr><th>Receipt</th><th>Customer</th><th>Recorded</th><th>Details</th><th class="right">Amount</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):$reversal=(float)$r['amount']<0;$reversed=str_starts_with($r['note'],'[REVERSED]');$paymentStatus=$reversal?'Reversal':($reversed?'Reversed':'Active');?><tr><td data-label="Receipt"><b><?=e(setting($pdo,'receipt_prefix','PAY'))?>-<?=str_pad((string)$r['id'],4,'0',STR_PAD_LEFT)?></b></td><td data-label="Customer"><b><?=e($r['customer'])?></b><?php if($r['mobile']):?><small><?=e($r['mobile'])?></small><?php endif;?></td><td data-label="Recorded"><?=e(date('d-m-Y',strtotime($r['created_at'])))?><small><?=e(date('h:i A',strtotime($r['created_at'])))?></small></td><td data-label="Details"><?=e($r['note']?:'—')?></td><td data-label="Amount" class="right <?=$reversal?'reversal-amount':''?>"><b>₹<?=money($r['amount'])?></b></td><td data-label="Status"><span class="payment-status <?=strtolower($paymentStatus)?>"><?=$paymentStatus?></span></td><td data-label="Action"><?php if(!$reversal&&!$reversed):?><form method="post" onsubmit="return confirm('Reverse this payment and restore the customer balance?')"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="reverse_payment"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn danger">Reverse</button></form><?php else:?>—<?php endif;?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="7" class="payment-empty">No payments match the selected filters.</td></tr><?php endif;?></tbody></table></div></section>
<script>document.addEventListener('DOMContentLoaded',()=>{const customer=document.getElementById('payment-customer'),balance=document.getElementById('payment-balance');if(!customer||!balance)return;const update=()=>{const option=customer.options[customer.selectedIndex];balance.textContent=option&&option.value?'Current outstanding: ₹'+option.dataset.balance:'Select a customer to view the current balance.';};customer.addEventListener('change',update);update();});</script><?php footer_html();exit;}

if($page==='whatsapp_reminders'){$customers=$pdo->query("SELECT c.*,COALESCE(bs.bill_total,0) bill_total,COALESCE(bs.bill_received,0) bill_received,COALESCE(ps.payment_total,0) payment_total FROM customers c LEFT JOIN (SELECT customer_id,SUM(subtotal) bill_total,SUM(amount_received) bill_received FROM bills WHERE status='active' GROUP BY customer_id) bs ON bs.customer_id=c.id LEFT JOIN (SELECT customer_id,SUM(amount) payment_total FROM payments GROUP BY customer_id) ps ON ps.customer_id=c.id ORDER BY c.name")->fetchAll();$readyCount=0;$missingCount=0;$totalDue=0.0;foreach($customers as &$c){$c['balance']=round((float)$c['opening_balance']+(float)$c['bill_total']-(float)$c['bill_received']-(float)$c['payment_total'],2);$c['phone']=whatsapp_number($c['mobile']);if($c['balance']>0){$totalDue+=$c['balance'];if($c['phone'])$readyCount++;else $missingCount++;}}unset($c);header_html('WhatsApp Reminders');?><div class="reports-heading"><div><h1>WhatsApp Balance Reminders</h1><p>Edit your reminder and send customer balances through WhatsApp</p></div></div><div class="report-summary whatsapp-summary"><div class="card"><small>Total Balance Due</small><b>₹<?=money($totalDue)?></b></div><div class="card"><small>Ready to Send</small><b><?=$readyCount?></b></div><div class="card"><small>Missing Number</small><b><?=$missingCount?></b></div></div><section class="card report-section" id="whatsapp-report"><div class="report-section-head"><div><h2>Reminder Message Setup</h2><p>Free click-to-WhatsApp sending; you confirm each message in WhatsApp</p></div><div><span class="report-status ready"><?=$readyCount?> Ready</span> <span class="report-status missing"><?=$missingCount?> Missing</span></div></div><form method="post" class="whatsapp-template no-report-print"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="save_whatsapp_template"><div class="whatsapp-template-editor"><p><label>Reminder Message</label><textarea id="reminder-template" name="reminder_template" maxlength="600" required><?=e(setting($pdo,'reminder_tamil'))?></textarea><small>Available placeholders: <b>{name}</b> for customer name and <b>{balance}</b> for current balance. {balance} is required.</small></p><div><label>Live Preview</label><div class="whatsapp-preview" id="whatsapp-preview"></div></div></div><div class="actions"><button>Save Template</button><button class="btn secondary" type="submit" name="reset_template" value="1" onclick="return confirm('Restore the default WhatsApp reminder message?')">Restore Default</button></div></form><div class="report-table-wrap"><table><thead><tr><th>Customer</th><th>WhatsApp Number</th><th class="right">Balance</th><th>Action</th></tr></thead><tbody><?php $hasDue=false;foreach($customers as $c):if($c['balance']<=0)continue;$hasDue=true;$msg=str_replace(['{name}','{balance}'],[$c['name'],money($c['balance'])],setting($pdo,'reminder_tamil'));?><tr><td class="report-customer"><b><?=e($c['name'])?></b><small><?=e($c['address'])?></small></td><td><?=$c['phone']?'+'.e($c['phone']):'—'?></td><td class="right balance-positive">₹<?=money($c['balance'])?></td><td><?=$c['phone']?'<span class="report-status ready">Ready</span>':'<span class="report-status missing">Add number</span>'?></td><td><?php if($c['phone']):?><a class="btn whatsapp-btn" target="_blank" href="https://wa.me/<?=e($c['phone'])?>?text=<?=rawurlencode($msg)?>">Send Reminder</a><?php else:?><a class="btn secondary" href="?page=customers&edit=<?=$c['id']?>">Add WhatsApp</a><?php endif;?></td></tr><?php endforeach;if(!$hasDue):?><tr><td colspan="5" class="report-empty">No outstanding balances.</td></tr><?php endif;?></tbody></table></div></section><script>document.addEventListener('DOMContentLoaded',()=>{const input=document.getElementById('reminder-template'),preview=document.getElementById('whatsapp-preview');if(!input||!preview)return;const update=()=>{preview.textContent=input.value.replaceAll('{name}','Kavin Kumar').replaceAll('{balance}','1,250.00')};input.addEventListener('input',update);update()});</script><?php footer_html();exit;}
if($page==='reports'){$from=trim($_GET['from']??date('Y-m-01'));$to=trim($_GET['to']??date('Y-m-d'));if(!preg_match('/^\\d{4}-\\d{2}-\\d{2}$/',$from))$from=date('Y-m-01');if(!preg_match('/^\\d{4}-\\d{2}-\\d{2}$/',$to))$to=date('Y-m-d');if($from>$to)[$from,$to]=[$to,$from];$fromTs=$from.' 00:00:00';$toTs=date('Y-m-d H:i:s',strtotime($to.' +1 day'));$customers=$pdo->query("SELECT c.*,COALESCE(bs.bill_total,0) bill_total,COALESCE(bs.bill_received,0) bill_received,COALESCE(ps.payment_total,0) payment_total FROM customers c LEFT JOIN (SELECT customer_id,SUM(subtotal) bill_total,SUM(amount_received) bill_received FROM bills WHERE status='active' GROUP BY customer_id) bs ON bs.customer_id=c.id LEFT JOIN (SELECT customer_id,SUM(amount) payment_total FROM payments GROUP BY customer_id) ps ON ps.customer_id=c.id ORDER BY c.name")->fetchAll();$totalOutstanding=0.0;$readyCount=0;$missingCount=0;foreach($customers as &$c){$c['balance']=round((float)$c['opening_balance']+(float)$c['bill_total']-(float)$c['bill_received']-(float)$c['payment_total'],2);$c['phone']=whatsapp_number($c['mobile']);if($c['balance']>0){$totalOutstanding+=$c['balance'];if($c['phone'])$readyCount++;else $missingCount++;}}unset($c);$ps=$pdo->prepare("SELECT bi.product_id,MAX(bi.english_name) english_name,MAX(bi.tamil_name) tamil_name,MAX(bi.unit) unit,SUM(bi.quantity) quantity,SUM(bi.amount) sales_total,SUBSTRING_INDEX(GROUP_CONCAT(bi.rate ORDER BY b.created_at DESC,b.id DESC SEPARATOR ','),',',1) last_rate,MAX(b.created_at) last_sale FROM bill_items bi JOIN bills b ON b.id=bi.bill_id WHERE b.status='active' AND b.created_at>=? AND b.created_at<? GROUP BY bi.product_id ORDER BY sales_total DESC,english_name");$ps->execute([$fromTs,$toTs]);$productRows=$ps->fetchAll();$productTotal=array_sum(array_map(fn($r)=>(float)$r['sales_total'],$productRows));header_html('Reports');?><div class="reports-heading"><div><span class="reports-kicker">BUSINESS INSIGHTS</span><h1>Reports</h1><p>Review outstanding balances, customer ledgers and product performance.</p></div><form method="get" class="card report-filter no-print"><input type="hidden" name="page" value="reports"><p><label>From</label><input type="date" name="from" value="<?=e($from)?>"></p><p><label>To</label><input type="date" name="to" value="<?=e($to)?>"></p><button>Apply</button><button type="button" class="btn secondary" onclick="window.print()">Print</button></form></div><div class="report-tabs no-print" role="tablist" aria-label="Choose report"><button type="button" class="report-tab active" data-report-tab="outstanding" role="tab" aria-selected="true"><span class="report-tab-icon">₹</span><span><b>Customer Outstanding</b><small>Who needs to pay</small></span><strong>₹<?=money($totalOutstanding)?></strong></button><button type="button" class="report-tab" data-report-tab="ledger-access" role="tab" aria-selected="false"><span class="report-tab-icon">≡</span><span><b>Customer Ledger</b><small>Open a customer statement</small></span><strong><?=count($customers)?></strong></button><button type="button" class="report-tab" data-report-tab="product-sales" role="tab" aria-selected="false"><span class="report-tab-icon">▥</span><span><b>Product Sales</b><small>Sales in selected period</small></span><strong>₹<?=money($productTotal)?></strong></button></div><div class="report-summary"><div class="card"><small>Total Outstanding</small><b>₹<?=money($totalOutstanding)?></b></div><div class="card"><small>Customers Due</small><b><?=count(array_filter($customers,fn($c)=>$c['balance']>0))?></b></div><div class="card"><small>Period Sales</small><b>₹<?=money($productTotal)?></b></div></div><section class="card report-section active" id="outstanding" data-report-panel="outstanding"><div class="report-section-head"><div><h2>Customer Outstanding</h2><p>Complete balance calculated from opening balance, active bills and payments</p></div><span class="balance-positive">₹<?=money($totalOutstanding)?></span></div><div class="report-table-wrap"><table><thead><tr><th>Customer</th><th class="right">Opening</th><th class="right">Bills</th><th class="right">Received</th><th class="right">Balance</th><th class="no-report-print">Actions</th></tr></thead><tbody><?php foreach(array_filter($customers,fn($c)=>$c["balance"]>0) as $c):$received=(float)$c['bill_received']+(float)$c['payment_total'];?><tr><td class="report-customer"><b><?=e($c['name'])?></b><small><?=e($c['mobile']?:$c['address'])?></small></td><td class="right">₹<?=money($c['opening_balance'])?></td><td class="right">₹<?=money($c['bill_total'])?></td><td class="right">₹<?=money($received)?></td><td class="right <?=$c['balance']>0?'balance-positive':'balance-clear'?>">₹<?=money($c['balance'])?></td><td class="no-report-print"><div class="report-actions"><a class="btn secondary" href="?page=ledger&customer_id=<?=$c['id']?>">Ledger</a><?php if($c['balance']>0&&$c['phone']):$msg=str_replace(['{name}','{balance}'],[$c['name'],money($c['balance'])],setting($pdo,'reminder_tamil'));?><a class="btn whatsapp-btn" target="_blank" href="https://wa.me/<?=e($c['phone'])?>?text=<?=rawurlencode($msg)?>">WhatsApp</a><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></section><section class="card report-section" id="ledger-access" data-report-panel="ledger-access"><div class="report-section-head"><div><h2>Customer Ledger</h2><p>Select a customer to view bills, payments and running balance</p></div></div><form method="get" class="ledger-launch"><input type="hidden" name="page" value="ledger"><p><label>Select Customer</label><select name="customer_id" required><option value="">Choose customer</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?> — ₹<?=money($c['balance'])?></option><?php endforeach;?></select></p><button>Open Ledger</button></form></section><section class="card report-section" id="product-sales" data-report-panel="product-sales"><div class="report-section-head"><div><h2>Product Sales</h2><p><?=e(date('d-m-Y',strtotime($from)))?> to <?=e(date('d-m-Y',strtotime($to)))?></p></div><b>₹<?=money($productTotal)?></b></div><div class="report-table-wrap"><table><thead><tr><th>S.No</th><th>Product</th><th>Tamil Name</th><th>Unit</th><th class="right">Quantity</th><th class="right">Last Rate</th><th class="right">Sales Value</th><th>Last Sold</th></tr></thead><tbody><?php if(!$productRows):?><tr><td colspan="8" class="report-empty">No product sales in this date range.</td></tr><?php endif;foreach($productRows as $i=>$r):?><tr><td><?=$i+1?></td><td><?=e($r['english_name'])?></td><td lang="ta"><?=e($r['tamil_name'])?></td><td><?=e($r['unit'])?></td><td class="right"><?=rtrim(rtrim(number_format((float)$r['quantity'],3),'0'),'.')?></td><td class="right">₹<?=money($r['last_rate'])?></td><td class="right"><b>₹<?=money($r['sales_total'])?></b></td><td><?=e(date('d-m-Y',strtotime($r['last_sale'])))?></td></tr><?php endforeach;?></tbody></table></div></section><script>document.addEventListener("DOMContentLoaded",()=>{const tabs=[...document.querySelectorAll("[data-report-tab]")],panels=[...document.querySelectorAll("[data-report-panel]")];const open=name=>{tabs.forEach(tab=>{const on=tab.dataset.reportTab===name;tab.classList.toggle("active",on);tab.setAttribute("aria-selected",on?"true":"false");});panels.forEach(panel=>panel.classList.toggle("active",panel.dataset.reportPanel===name));history.replaceState(null,"","#"+name);};tabs.forEach(tab=>tab.addEventListener("click",()=>open(tab.dataset.reportTab)));const requested=location.hash.slice(1);if(tabs.some(tab=>tab.dataset.reportTab===requested))open(requested);});</script><?php footer_html();exit;}
if($page==='new_bill'){$bill=null;$existing=[];$editBillId=(int)($_GET['id']??0);if($editBillId){$s=$pdo->prepare('SELECT * FROM bills WHERE id=? AND status="active"');$s->execute([$editBillId]);$bill=$s->fetch();if(!$bill)exit('Bill not found.');$s=$pdo->prepare('SELECT * FROM bill_items WHERE bill_id=?');$s->execute([$bill['id']]);$existing=$s->fetchAll();}$customers=$pdo->query('SELECT * FROM customers ORDER BY name')->fetchAll();$selectedCustomer=null;foreach($customers as $candidate){if(($bill['customer_id']??0)==$candidate['id']){$selectedCustomer=$candidate;break;}}$displayBillNo=$bill?(int)$bill['bill_no']:(int)setting($pdo,'next_bill_no','1');$displayBillDate=$bill?date('Y-m-d',strtotime($bill['created_at'])):date('Y-m-d');header_html($bill?'Edit Bill':'New Bill');?><div class="page-heading"><div><h1><?=$bill?'Edit Bill #'.str_pad($bill['bill_no'],4,'0',STR_PAD_LEFT):'New Bill'?></h1></div></div><div class="price-popup" id="price-history-popup" hidden><div class="price-popup-card"><div class="price-popup-head"><div><small>Customer Price History</small><h3 id="price-popup-title">Last 5 Bills</h3></div><button type="button" class="price-popup-close" aria-label="Close">×</button></div><div class="price-popup-body"><table><thead><tr><th>Bill No.</th><th>Date</th><th class="right">Qty</th><th class="right">Rate</th></tr></thead><tbody id="price-popup-rows"></tbody></table></div></div></div><form method="post" class="card bill-form" id="bill-form"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="save_bill"><input type="hidden" name="bill_id" value="<?=e($bill['id']??'')?>"><div class="bill-top"><div class="customer-area"><div class="customer-search-row"><div class="customer-field searchbox"><label>Customer Name</label><input id="bill-customer-search" placeholder="Type customer name or mobile" autocomplete="off" value="<?=e($selectedCustomer?($selectedCustomer['name'].' — '.(trim($selectedCustomer['address'])!==''?$selectedCustomer['address']:'Address not available')):'')?>" required><button type="button" class="customer-clear" aria-label="Clear selected customer" <?=$selectedCustomer?'':'hidden'?>>×</button><input type="hidden" id="bill-customer" name="customer_id" value="<?=e($selectedCustomer['id']??'')?>" data-balance="<?=$selectedCustomer?customer_balance($pdo,(int)$selectedCustomer['id'],$bill['id']??null):0?>"><div class="suggestions customer-suggestions" id="customer-suggestions"><?php foreach($customers as $c):$cb=customer_balance($pdo,(int)$c['id'],$bill['id']??null);?><button type="button" data-id="<?=$c['id']?>" data-name="<?=e($c['name'])?>" data-mobile="<?=e($c['mobile'])?>" data-address="<?=e($c['address'])?>" data-search="<?=e(strtolower($c['name'].' '.$c['mobile']))?>" data-balance="<?=$cb?>"><strong><?=e($c['name'])?></strong><small><?=trim($c['address'])!==''?e($c['address']):'Address not available'?></small></button><?php endforeach;?></div></div><a class="btn secondary add-customer-link" href="?page=customers">＋ Add Customer</a></div></div><div class="bill-info-stack"><div><label>Bill Date</label><input type="date" name="bill_date" value="<?=e($displayBillDate)?>" required></div><div><small>Bill No.</small><b>#<?=str_pad((string)$displayBillNo,4,'0',STR_PAD_LEFT)?></b></div></div></div><div class="items-table-head"><span>S.No</span><span>Product (English Search)</span><span>Qty</span><span>Unit</span><span>Rate</span><span>Amount</span><span></span></div><div id="items"></div><div class="bill-footer"><div class="bill-summary"><div><small>Previous Balance</small><b>₹<span id="previous-balance">0.00</span></b></div><div><small>Current Bill</small><b>₹<span id="subtotal">0.00</span></b></div><div><label>Amount Received</label><input id="bill-received" type="number" name="amount_received" min="0" step="0.01" value="<?=e($bill['amount_received']??'0')?>"></div><div class="closing-box"><small>Closing Balance</small><b>₹<span id="closing-balance">0.00</span></b></div></div><div class="bill-actions"><a class="btn secondary" href="<?=$bill?'?page=bills':'index.php'?>">Cancel</a><button class="save-bill"><?=$bill?'Save Changes':'Save & Create Bill'?></button></div></div></form><template id="item-template"><div class="item-row"><div class="sno-cell"><label>S.No</label><b class="row-number">1</b></div><div class="product-cell searchbox"><label>Product</label><input class="product-search" name="english_name[]" autocomplete="off" required><input type="hidden" class="product-id" name="product_id[]"><input type="hidden" class="tamil-name" name="tamil_name[]"><div class="suggestions"></div></div><div><label>Qty</label><input class="qty numeric" name="quantity[]" type="number" min="0.001" step="0.001" value="1"></div><div><label>Unit</label><input class="unit" name="unit[]" readonly></div><div><label>Rate</label><input class="rate numeric" name="rate[]" type="number" min="0" step="0.01"></div><div><label>Amount</label><input class="amount numeric" readonly></div><button type="button" class="danger remove" aria-label="Remove row">×</button></div></template><?php if($existing):?><script>window.__editingBill=true;document.addEventListener('DOMContentLoaded',()=>{<?php foreach($existing as $x):?>addRow(<?=json_encode(['product_id'=>$x['product_id'],'english_name'=>$x['english_name'],'tamil_name'=>$x['tamil_name'],'unit'=>$x['unit'],'default_rate'=>$x['rate']],JSON_UNESCAPED_UNICODE)?>);var r=document.querySelector('#items .item-row:last-child');r.querySelector('.qty').value=<?=json_encode($x['quantity'])?>;recalc();<?php endforeach;?>addRow({},true);});</script><?php endif;footer_html();exit;}

if($page==='bills'){$rows=$pdo->query('SELECT b.*,c.name customer FROM bills b JOIN customers c ON c.id=b.customer_id WHERE b.status="active" ORDER BY b.id DESC')->fetchAll();header_html('Bills');?><div class="actions"><h1 style="margin-right:auto">Bills</h1><a class="btn" href="?page=new_bill">New Bill</a></div><div class="card"><table><tr><th>Bill No.</th><th>Date</th><th>Customer</th><th class="right">Total</th><th>Actions</th></tr><?php foreach($rows as $r):?><tr><td><?=str_pad($r['bill_no'],4,'0',STR_PAD_LEFT)?></td><td><?=e(date('d-m-Y',strtotime($r['created_at'])))?></td><td><?=e($r['customer'])?></td><td class="right">₹<?=money($r['subtotal'])?></td><td><div class="actions bill-row-actions"><a class="btn secondary" href="?page=view_bill&id=<?=$r['id']?>">View / Print</a><a class="btn" href="?page=new_bill&id=<?=$r['id']?>">Edit</a></div></td></tr><?php endforeach;?></table></div><?php footer_html();exit;}

if($page==='view_bill'||$page==='public_bill'){$public=$page==='public_bill';if($public){$s=$pdo->prepare('SELECT b.*,c.name customer,c.mobile,c.address FROM bills b JOIN customers c ON c.id=b.customer_id WHERE b.share_token=? AND b.status="active"');$s->execute([$_GET['token']??'']);}else{$s=$pdo->prepare('SELECT b.*,c.name customer,c.mobile,c.address FROM bills b JOIN customers c ON c.id=b.customer_id WHERE b.id=? AND b.status="active"');$s->execute([(int)$_GET['id']]);}$bill=$s->fetch();if(!$bill)exit('Bill not found.');$s=$pdo->prepare('SELECT * FROM bill_items WHERE bill_id=?');$s->execute([$bill['id']]);$items=$s->fetchAll();$balance=isset($bill['closing_balance'])&&$bill['closing_balance']!==null?(float)$bill['closing_balance']:customer_balance($pdo,(int)$bill['customer_id']);$previousBalance=round($balance-(float)$bill['subtotal']+(float)$bill['amount_received'],2);$shareUrl=$config['base_url'].'/?page=public_bill&token='.$bill['share_token'];$billPhone=whatsapp_number($bill['mobile']);$pdfName='SGAS-Bill-'.str_pad($bill['bill_no'],4,'0',STR_PAD_LEFT).'.pdf';header_html('Bill #'.$bill['bill_no']);?><div class="actions no-print"><?php if(!$public):?><a class="btn secondary" href="?page=bills">Back</a><a class="btn" href="?page=new_bill&id=<?=$bill['id']?>">Edit</a><?php endif;?><button onclick="downloadBillPdf('<?=e($pdfName)?>')">Download PDF</button><button onclick="shareBillPdf('<?=e($pdfName)?>')">Share PDF on WhatsApp</button></div><div class="card bill-print"><div class="bill-paper"><header class="bill-paper-title"><h1><?=e(setting($pdo,'bill_header',setting($pdo,'shop_name','SGAS')))?></h1></header><div class="bill-print-meta"><div class="bill-customer-block"><div><b>Customer</b><span>:</span><strong><?=e($bill['customer'])?></strong></div><div><b>Address</b><span>:</span><strong><?=trim($bill['address'])!==''?nl2br(e($bill['address'])):'—'?></strong></div></div><div class="bill-number-block"><div><b>Bill No</b><span>:</span><strong><?=str_pad($bill['bill_no'],4,'0',STR_PAD_LEFT)?></strong></div><div><b>Bill Date</b><span>:</span><strong><?=e(date('d-m-Y',strtotime($bill['created_at'])))?></strong></div></div></div><table class="bill-items-print"><colgroup><col class="col-sno"><col class="col-rate"><col class="col-product"><col class="col-qty"><col class="col-unit"><col class="col-amount"></colgroup><thead><tr><th>S.No</th><th class="right">Rate</th><th>Product</th><th class="right">Qty</th><th>Unit</th><th class="right">Amount</th></tr></thead><tbody><?php foreach($items as $i=>$x):?><tr><td><?=$i+1?></td><td class="right"><?=money($x['rate'])?></td><td lang="ta"><?=e(setting($pdo,'print_language','tamil')==='english'?$x['english_name']:$x['tamil_name'])?></td><td class="right"><?=rtrim(rtrim(number_format($x['quantity'],3),'0'),'.')?></td><td><?=e($x['unit'])?></td><td class="right"><?=money($x['amount'])?></td></tr><?php endforeach;?><tr class="bill-table-filler" aria-hidden="true"><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody><tfoot><tr><td colspan="5" class="right"><b>Total</b></td><td class="right"><b><?=money($bill['subtotal'])?></b></td></tr></tfoot></table><div class="bill-print-totals"><table class="balance-summary" lang="ta"><?php if(setting($pdo,'show_previous_balance','1')==='1'):?><tr><td>பழைய நிலுவை</td><td>:</td><td class="right"><b><?=money($previousBalance)?></b></td></tr><?php endif;?><tr><td>தற்போதைய பில்</td><td>:</td><td class="right"><b><?=money($bill['subtotal'])?></b></td></tr><?php if(setting($pdo,'show_amount_received','1')==='1'&&(float)$bill['amount_received']>0):?><tr><td>பெற்ற தொகை</td><td>:</td><td class="right"><b><?=money($bill['amount_received'])?></b></td></tr><?php endif;?><tr><td>மொத்த நிலுவை</td><td>:</td><td class="right"><b><?=money($balance)?></b></td></tr></table><div class="current-bill-total"><span>Grand Total</span><b><?=money($bill['subtotal'])?></b></div></div></div></div><script src="https://cdnjs.cloudflare.com/ajax/libs/html2pdf.js/0.10.1/html2pdf.bundle.min.js"></script><?php footer_html();exit;}

